def canonical(cell, ly):
    result=[]
    for li in ly.layer_indexes():
        info=ly.get_info(li)
        for s in cell.shapes(li).each():
            shape=('TEXT '+s.text.string+' '+s.text.trans.to_s()) if s.is_text() else s.to_s()
            result.append((info.layer,info.datatype,shape))
    return hashlib.sha256(json.dumps(sorted(result),ensure_ascii=True).encode()).hexdigest()


def generate(output_dir=None):
    # The workflow executes this file in submissions/KLayout Python.
    folder=Path(output_dir) if output_dir else Path(__file__).resolve().parent.parent
    folder.mkdir(parents=True,exist_ok=True)
    ly=k.Layout();ly.dbu=0.001
    assets=Path(find_spec('siepic_ebeam_pdk').origin).parent/'gds'/'EBeam'
    cells={}
    for name,spec in PLAN.items():
        if spec['kind']=='official':
            original=k.Layout();original.read(str(assets/spec['file']))
            cell=original.cell(name)
            if cell is None or canonical(cell,original)!=spec['sha256']:
                raise RuntimeError('Official PDK asset differs from validated source: '+name)
            new=ly.create_cell(name)
            # Copy local shapes only; preserve shared child cells through PLAN.
            for li in original.layer_indexes():
                for shape in cell.shapes(li).each():
                    new.shapes(ly.layer(original.get_info(li))).insert(shape)
            cells[name]=new
        else:
            cells[name]=ly.create_cell(name)
    for name,spec in PLAN.items():
        c=cells[name]
        if spec['kind']=='straight':
            length=spec['length_nm']
            c.shapes(ly.layer(1,0)).insert(k.Box(0,-250,length,250))
            c.shapes(ly.layer(68,0)).insert(k.Box(0,-750,length,750))
            for pname,x,direction in [('o1',0,-1),('o2',length,1)]:
                c.shapes(ly.layer(1,10)).insert(k.Path([k.Point(x-direction*50,0),k.Point(x+direction*50,0)],500))
                c.shapes(ly.layer(1,10)).insert(k.Text(pname,k.Trans(x,0)))
            for layer,text in spec['texts']:
                c.shapes(ly.layer(*layer)).insert(k.Text.from_s(text))
        elif spec['kind']=='geometry':
            # Validated, sampled Euler profiles, not right-angle silicon paths.
            classes={'polygon':k.Polygon,'simple_polygon':k.SimplePolygon,
                     'box':k.Box,'path':k.Path,'text':k.Text}
            for layer,kind,value in spec['shapes']:
                c.shapes(ly.layer(*layer)).insert(classes[kind].from_s(value))
        if spec['kind'] in ['assembly','official']:
            for child,angle,mirror,x,y,role in spec['instances']:
                ref=c.insert(k.CellInstArray(cells[child].cell_index(),k.ICplxTrans(1,angle,mirror,x,y)))
                if role is not None:ref.set_property(0,role)
            for layer,text in spec.get('texts',[]):
                c.shapes(ly.layer(*layer)).insert(k.Text.from_s(text))
            for layer,box in spec.get('boxes',[]):
                c.shapes(ly.layer(*layer)).insert(k.Box.from_s(box))
    top=cells[TOP]
    for li in list(ly.layer_indexes()):
        if all(c.shapes(li).is_empty() for c in ly.each_cell()):ly.delete_layer(li)
    assert top.dbbox().width()<=605 and top.dbbox().height()<=410
    target=folder/(TOP+'.oas')
    options=k.SaveLayoutOptions();options.set_format_from_filename(str(target));options.write_context_info=False
    top.write(str(target),options)
    # Validate actual serialized topology before reporting successful generation.
    import SiEPIC
    import siepic_ebeam_pdk
    from SiEPIC.utils import get_technology_by_name
    from SiEPIC import _globals
    check=k.Layout();check.read(str(target));check.TECHNOLOGY=get_technology_by_name('EBeam')
    nets,components=check.top_cell().identify_nets()
    assert nets and components
    assert all(c.pins for c in components)
    assert all(p.net.idx is not None for c in components for p in c.pins if p.type==_globals.PIN_TYPES.OPTICAL)
    print(str(target))
    return target


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--output-dir',type=Path)
    generate(parser.parse_args().output_dir)
